window.__AI_AGENTS_LESSONS__ = window.__AI_AGENTS_LESSONS__ || {};
window.__AI_AGENTS_LESSONS__["00-course-setup"] = {"slug": "00-course-setup", "en": {"title": "Course Setup", "sections": [{"id": "ai-sec-1", "level": 2, "title": "Introduction"}, {"id": "ai-sec-2", "level": 2, "title": "Join Other Learners and Get Help"}, {"id": "ai-sec-3", "level": 2, "title": "Clone or Fork this Repo"}, {"id": "ai-sec-4", "level": 3, "title": "Shallow Clone (recommended for workshop / Codespaces)"}, {"id": "ai-sec-5", "level": 2, "title": "Running the Code"}, {"id": "ai-sec-6", "level": 2, "title": "Requirements"}, {"id": "ai-sec-7", "level": 2, "title": "Setup VSCode"}, {"id": "ai-sec-8", "level": 2, "title": "Set Up Microsoft Foundry and Microsoft Foundry Agent Service"}, {"id": "ai-sec-9", "level": 3, "title": "Step 1: Create a Microsoft Foundry Project"}, {"id": "ai-sec-10", "level": 3, "title": "Step 2: Retrieve Your Project Endpoint and Model Deployment Name"}, {"id": "ai-sec-11", "level": 3, "title": "Step 3: Sign in to Azure with `az login`"}, {"id": "ai-sec-12", "level": 3, "title": "Step 4: Create Your `.env` File"}, {"id": "ai-sec-13", "level": 3, "title": "Step 5: Install Python Dependencies"}, {"id": "ai-sec-14", "level": 2, "title": "Optional Setup: Azure AI Search (Lessons 5 and 16)"}, {"id": "ai-sec-15", "level": 2, "title": "Additional Setup for Lessons that Call Azure OpenAI Directly (Lessons 6 and 8)"}, {"id": "ai-sec-16", "level": 2, "title": "Alternative Provider: MiniMax (OpenAI-Compatible)"}, {"id": "ai-sec-17", "level": 2, "title": "Alternative Provider: Novita AI (OpenAI-Compatible)"}, {"id": "ai-sec-18", "level": 2, "title": "Alternative Provider: Foundry Local (Run Models On-Device)"}, {"id": "ai-sec-19", "level": 2, "title": "Additional Setup for Lesson 8 (Bing Grounding Workflow)"}, {"id": "ai-sec-20", "level": 2, "title": "Troubleshooting"}, {"id": "ai-sec-21", "level": 3, "title": "SSL Certificate Verification Errors on macOS"}, {"id": "ai-sec-22", "level": 2, "title": "Stuck Somewhere?"}, {"id": "ai-sec-23", "level": 2, "title": "Next Lesson"}], "html": "<h1 id=\"ai-sec-1\" class=\"cs-h1\">Course Setup</h1>\n<h2 id=\"ai-sec-1\" class=\"cs-h2\">Introduction</h2>\n<p>This lesson will cover how to run the code samples of this course.</p>\n<h2 id=\"ai-sec-2\" class=\"cs-h2\">Join Other Learners and Get Help</h2>\n<p>Before you begin cloning your repo, join the <a href=\"https://aka.ms/ai-agents/discord\" target=\"_blank\" rel=\"noopener noreferrer\">AI Agents For Beginners Discord channel</a> to get any help with setup, any questions about the course, or to connect with other learners.</p>\n<h2 id=\"ai-sec-3\" class=\"cs-h2\">Clone or Fork this Repo</h2>\n<p>To begin, please clone or fork the GitHub Repository. This will make your own version of the course material so that you can run, test, and tweak the code!</p>\n<p>This can be done by clicking the link to &lt;a href=\"https://github.com/microsoft/ai-agents-for-beginners/fork\" target=\"_blank\"&gt;fork the repo&lt;/a&gt;</p>\n<p>You should now have your own forked version of this course in the following link:</p>\n<blockquote class=\"cs-quote\">[Figure: Forked Repo]</blockquote>\n<h3 id=\"ai-sec-4\" class=\"cs-h3\">Shallow Clone (recommended for workshop / Codespaces)</h3>\n<blockquote class=\"cs-quote\">The full repository can be large (~3 GB) when you download full history and all files. If you're only attending the workshop or only need a few lesson folders, a shallow clone (or a sparse clone) downloads much less.</blockquote>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Quick shallow clone — minimal history, all files</h4>\n<p>Replace <code>&lt;your-username&gt;</code> in the below commands with your fork URL (or the upstream URL if you prefer).</p>\n<p>To clone only the latest commit history (small download):</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<p>To clone a specific branch:</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 --branch &lt;branch-name&gt; https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Partial (sparse) clone — minimal blobs + only selected folders</h4>\n<p>This uses partial clone and sparse-checkout (requires Git 2.25+ and recommended modern Git with partial clone support):</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 --filter=blob:none --sparse https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<p>Traverse into the repo folder:</p>\n<pre class=\"cs-code\"><code>cd ai-agents-for-beginners</code></pre>\n<p>Then specify which folders you want (example below shows two folders):</p>\n<pre class=\"cs-code\"><code>git sparse-checkout set 00-course-setup 01-intro-to-ai-agents</code></pre>\n<p>After cloning and verifying the files, if you only need files and want to free space (no git history), please delete the repository metadata (💀irreversible — you will lose all Git functionality):</p>\n<pre class=\"cs-code\"><code># zsh/bash\nrm -rf .git</code></pre>\n<pre class=\"cs-code\"><code># PowerShell\nRemove-Item -Recurse -Force .git</code></pre>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Using GitHub Codespaces (recommended to avoid local large downloads)</h4>\n<ul class=\"cs-list\">\n<li>Create a new Codespace for this repo via the <a href=\"https://github.com/codespaces\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub UI</a>.</li>\n</ul>\n<ul class=\"cs-list\">\n<li>In the terminal of the newly created codespace, run one of the shallow/sparse clone commands above to bring only the lesson folders you need into the Codespace workspace.</li>\n<li>Optional: after cloning inside Codespaces, remove .git to reclaim extra space (see removal commands above).</li>\n<li>Note: If you prefer to open the repo directly in Codespaces (without an extra clone), be aware Codespaces will construct the devcontainer environment and may still provision more than you need.</li>\n</ul>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Tips</h4>\n<ul class=\"cs-list\">\n<li>Always replace the clone URL with your fork if you want to edit/commit.</li>\n<li>If you later need more history or files, you can fetch them or adjust sparse-checkout to include additional folders.</li>\n</ul>\n<h2 id=\"ai-sec-5\" class=\"cs-h2\">Running the Code</h2>\n<p>This course offers a series of Jupyter Notebooks that you can run with to get hands-on experience building AI Agents.</p>\n<p>The code samples use <strong>Microsoft Agent Framework (MAF)</strong> with the <code>FoundryChatClient</code>, which connects to <strong>Microsoft Foundry Agent Service V2</strong> (the Responses API) through <strong>Microsoft Foundry</strong>.</p>\n<p>All Python notebooks are labelled <code>*-python-agent-framework.ipynb</code>.</p>\n<h2 id=\"ai-sec-6\" class=\"cs-h2\">Requirements</h2>\n<ul class=\"cs-list\">\n<li>Python 3.12+</li>\n<li><strong>NOTE</strong>: If you don't have Python3.12 installed, ensure you install it.  Then create your venv using python3.12 to ensure the correct versions are installed from the requirements.txt file.</li>\n</ul>\n<blockquote class=\"cs-quote\">Example</blockquote>\n<p>Create Python venv directory:</p>\n<pre class=\"cs-code\"><code>    python -m venv venv</code></pre>\n<p>Then activate venv environment for:</p>\n<pre class=\"cs-code\"><code>    # zsh/bash\n    source venv/bin/activate</code></pre>\n<pre class=\"cs-code\"><code>    # Command Prompt for Windows\n    venv\\Scripts\\activate</code></pre>\n<ul class=\"cs-list\">\n<li>.NET 10+: For the sample codes using .NET, ensure you install <a href=\"https://dotnet.microsoft.com/download/dotnet/10.0\" target=\"_blank\" rel=\"noopener noreferrer\">.NET 10 SDK</a> or later. Then, check your installed .NET SDK version:</li>\n</ul>\n<pre class=\"cs-code\"><code>    dotnet --list-sdks</code></pre>\n<ul class=\"cs-list\">\n<li><strong>Azure CLI</strong> — Required for authentication. Install from <a href=\"https://aka.ms/installazurecli\" target=\"_blank\" rel=\"noopener noreferrer\">aka.ms/installazurecli</a>.</li>\n<li><strong>Azure Subscription</strong> — For access to Microsoft Foundry and Microsoft Foundry Agent Service.</li>\n<li><strong>Microsoft Foundry Project</strong> — A project with a deployed model (e.g., <code>gpt-5-mini</code>). See <strong>Step 1</strong> below.</li>\n</ul>\n<p>We have included a <code>requirements.txt</code> file in the root of this repository that contains all the required Python packages to run the code samples.</p>\n<p>You can install them by running the following command in your terminal at the root of the repository:</p>\n<pre class=\"cs-code\"><code>pip install -r requirements.txt</code></pre>\n<p>We recommend creating a Python virtual environment to avoid any conflicts and issues.</p>\n<h2 id=\"ai-sec-7\" class=\"cs-h2\">Setup VSCode</h2>\n<p>Make sure that you are using the right version of Python in VSCode.</p>\n<h2 id=\"ai-sec-8\" class=\"cs-h2\">Set Up Microsoft Foundry and Microsoft Foundry Agent Service</h2>\n<h3 id=\"ai-sec-9\" class=\"cs-h3\">Step 1: Create a Microsoft Foundry Project</h3>\n<p>You need a Microsoft Foundry <strong>project</strong> with a deployed model to run the notebooks. Create the project directly in the current Microsoft Foundry experience; a hub is not required.</p>\n<ol class=\"cs-list\">\n<li>Go to <a href=\"https://ai.azure.com\" target=\"_blank\" rel=\"noopener noreferrer\">ai.azure.com</a> and sign in with your Azure account.</li>\n<li>Select <strong>Create project</strong> and follow the prompts to create your project.</li>\n<li>In the project, deploy a model (e.g., <code>gpt-5-mini</code>) from <strong>Models + Endpoints</strong> → <strong>Deploy model</strong>.</li>\n</ol>\n<h3 id=\"ai-sec-10\" class=\"cs-h3\">Step 2: Retrieve Your Project Endpoint and Model Deployment Name</h3>\n<p>From your project in the Microsoft Foundry portal:</p>\n<ul class=\"cs-list\">\n<li><strong>Project Endpoint</strong> — Go to the <strong>Overview</strong> page and copy the endpoint URL.</li>\n</ul>\n<blockquote class=\"cs-quote\">[Figure: Project Connection String]</blockquote>\n<ul class=\"cs-list\">\n<li><strong>Model Deployment Name</strong> — Go to <strong>Models + Endpoints</strong>, select your deployed model, and note the <strong>Deployment name</strong> (e.g., <code>gpt-5-mini</code>).</li>\n</ul>\n<h3 id=\"ai-sec-11\" class=\"cs-h3\">Step 3: Sign in to Azure with <code>az login</code></h3>\n<p>Most notebooks authenticate through your <strong>Azure CLI sign-in</strong> — using <code>AzureCliCredential</code> or <code>DefaultAzureCredential</code> (both pick up your <code>az login</code> session) from the <code>azure-identity</code> package — so they do not require API keys. A few lessons and optional integrations use API keys; check each lesson's prerequisites for any additional environment variables. This requires you to be signed in via the Azure CLI.</p>\n<ol class=\"cs-list\">\n<li><strong>Install the Azure CLI</strong> if you haven't already: <a href=\"https://aka.ms/installazurecli\" target=\"_blank\" rel=\"noopener noreferrer\">aka.ms/installazurecli</a></li>\n</ol>\n<ol class=\"cs-list\">\n<li><strong>Sign in</strong> by running:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az login</code></pre>\n<p>Or if you're in a remote/Codespace environment without a browser:</p>\n<pre class=\"cs-code\"><code>    az login --use-device-code</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Select your subscription</strong> if prompted — choose the one containing your Foundry project.</li>\n</ol>\n<ol class=\"cs-list\">\n<li><strong>Verify</strong> you're signed in:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az account show</code></pre>\n<blockquote class=\"cs-quote\"><strong>Why <code>az login</code>?</strong> The notebooks authenticate using <code>AzureCliCredential</code> (or <code>DefaultAzureCredential</code>, which also picks up your Azure CLI sign-in) from the <code>azure-identity</code> package. This means your Azure CLI session provides the credentials — no API keys or secrets in your <code>.env</code> file. This is a <a href=\"https://learn.microsoft.com/azure/developer/ai/keyless-connections\" target=\"_blank\" rel=\"noopener noreferrer\">security best practice</a>.</blockquote>\n<h3 id=\"ai-sec-12\" class=\"cs-h3\">Step 4: Create Your <code>.env</code> File</h3>\n<p>Copy the example file:</p>\n<pre class=\"cs-code\"><code># zsh/bash\ncp .env.example .env</code></pre>\n<pre class=\"cs-code\"><code># PowerShell\nCopy-Item .env.example .env</code></pre>\n<p>Open <code>.env</code> and fill in these two values:</p>\n<pre class=\"cs-code\"><code>AZURE_AI_PROJECT_ENDPOINT=https://&lt;your-project&gt;.services.ai.azure.com/api/projects/&lt;your-project-id&gt;\nAZURE_AI_MODEL_DEPLOYMENT_NAME=gpt-5-mini</code></pre>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>AZURE_AI_PROJECT_ENDPOINT</code></td><td>Foundry portal → your project → <strong>Overview</strong> page</td></tr>\n<tr><td><code>AZURE_AI_MODEL_DEPLOYMENT_NAME</code></td><td>Foundry portal → <strong>Models + Endpoints</strong> → your deployed model's name</td></tr>\n</tbody></table></div>\n<p>That's it for most lessons! The notebooks will authenticate automatically through your <code>az login</code> session.</p>\n<h3 id=\"ai-sec-13\" class=\"cs-h3\">Step 5: Install Python Dependencies</h3>\n<pre class=\"cs-code\"><code>pip install -r requirements.txt</code></pre>\n<p>We recommend running this inside the virtual environment you created earlier.</p>\n<h2 id=\"ai-sec-14\" class=\"cs-h2\">Optional Setup: Azure AI Search (Lessons 5 and 16)</h2>\n<p>The Lesson 5 (Agentic RAG) and Lesson 16 notebooks run out of the box with an <strong>in-memory knowledge base</strong> — no extra Azure resources needed. If you want to back them with a real <strong>Azure AI Search</strong> index, note that the <strong>Lesson 16 notebook currently uses key-based authentication</strong>: it switches from in-memory search to Azure AI Search only when <strong>both</strong> <code>AZURE_SEARCH_SERVICE_ENDPOINT</code> <strong>and</strong> <code>AZURE_SEARCH_API_KEY</code> are set, and otherwise stays on in-memory search — so to run it against a real index you must set the admin key as well. Keyless authentication with Microsoft Entra ID (RBAC) is the recommended approach for your own production code, consistent with the <code>az login</code> flow used everywhere else in this course.</p>\n<p>The RBAC steps below apply to the setup-guide samples and your own code. They do not enable keyless authentication in the Lesson 16 notebook; Lesson 16 still requires both the endpoint and admin key to use Azure AI Search.</p>\n<ol class=\"cs-list\">\n<li><strong>Enable role-based access</strong> on your search service:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az search service update --name &lt;service-name&gt; --resource-group &lt;resource-group&gt; --auth-options aadOrApiKey</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Assign yourself the required roles</strong> (create/load indexes and query):</li>\n</ol>\n<pre class=\"cs-code\"><code>    az role assignment create --assignee &lt;your-user-or-principal-id&gt; --role &quot;Search Service Contributor&quot; --scope $(az search service show -g &lt;resource-group&gt; -n &lt;service-name&gt; --query id -o tsv)\n    az role assignment create --assignee &lt;your-user-or-principal-id&gt; --role &quot;Search Index Data Contributor&quot; --scope $(az search service show -g &lt;resource-group&gt; -n &lt;service-name&gt; --query id -o tsv)</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Add the endpoint</strong> to your <code>.env</code> file:</li>\n</ol>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>AZURE_SEARCH_SERVICE_ENDPOINT</code></td><td>Azure portal → your <strong>Azure AI Search</strong> resource → <strong>Overview</strong> → URL</td></tr>\n<tr><td><code>AZURE_SEARCH_API_KEY</code></td><td>Required (with the endpoint) to enable Azure AI Search in the Lesson 16 notebook, which uses key-based auth. Azure portal → <strong>Settings</strong> → <strong>Keys</strong> → primary admin key</td></tr>\n</tbody></table></div>\n<blockquote class=\"cs-quote\"><strong>Why keyless?</strong> Admin keys grant full write access to your search service and can leak via <code>.env</code> files. With RBAC, your <code>az login</code> identity is used instead — the same keyless Entra ID pattern the course notebooks use (via <code>AzureCliCredential</code> / <code>DefaultAzureCredential</code>). See <a href=\"https://learn.microsoft.com/azure/search/search-security-rbac\" target=\"_blank\" rel=\"noopener noreferrer\">Connect to Azure AI Search using roles</a>.</blockquote>\n<p>See the <strong>Azure AI Search setup guide</strong> for full index-creation samples in Python and .NET.</p>\n<h2 id=\"ai-sec-15\" class=\"cs-h2\">Additional Setup for Lessons that Call Azure OpenAI Directly (Lessons 6 and 8)</h2>\n<p>Some notebooks in lessons 6 and 8 call <strong>Azure OpenAI</strong> directly (using the <strong>Responses API</strong>) instead of going through a Microsoft Foundry project. These samples previously used GitHub Models, which is deprecated and does not support the Responses API. Add these variables to your <code>.env</code> file:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>AZURE_OPENAI_ENDPOINT</code></td><td>Azure portal → your <strong>Azure OpenAI</strong> resource → <strong>Keys and Endpoint</strong> → Endpoint (e.g. <code>https://&lt;your-resource&gt;.openai.azure.com</code>)</td></tr>\n<tr><td><code>AZURE_OPENAI_DEPLOYMENT</code></td><td>The name of your deployed model (e.g. <code>gpt-5-mini</code>) that supports the Responses API</td></tr>\n<tr><td><code>AZURE_OPENAI_API_KEY</code></td><td>Optional — only if you use key-based auth instead of <code>az login</code> / Entra ID</td></tr>\n</tbody></table></div>\n<blockquote class=\"cs-quote\">The Responses API uses the stable <code>/openai/v1/</code> endpoint, so no <code>api-version</code> is required. Sign in with <code>az login</code> to use keyless Entra ID authentication.</blockquote>\n<h2 id=\"ai-sec-16\" class=\"cs-h2\">Alternative Provider: MiniMax (OpenAI-Compatible)</h2>\n<p><a href=\"https://platform.minimaxi.com/\" target=\"_blank\" rel=\"noopener noreferrer\">MiniMax</a> provides large-context models (up to 204K tokens) through an OpenAI-compatible API. Since the Microsoft Agent Framework's <code>OpenAIChatClient</code> works with any OpenAI-compatible endpoint, you can use MiniMax as a drop-in alternative for lessons that use <code>OpenAIChatClient</code>.</p>\n<p>Add these variables to your <code>.env</code> file:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>MINIMAX_API_KEY</code></td><td><a href=\"https://platform.minimaxi.com/\" target=\"_blank\" rel=\"noopener noreferrer\">MiniMax Platform</a> → API Keys</td></tr>\n<tr><td><code>MINIMAX_BASE_URL</code></td><td>Use <code>https://api.minimax.io/v1</code> (default value)</td></tr>\n<tr><td><code>MINIMAX_MODEL_ID</code></td><td>Model name to use (e.g., <code>MiniMax-M3</code>)</td></tr>\n</tbody></table></div>\n<p><strong>Example models</strong>: <code>MiniMax-M3</code> (recommended), <code>MiniMax-M2.7</code>, <code>MiniMax-M2.7-highspeed</code> (faster responses). Model names and availability can change over time, and access to a given model may depend on your account.</p>\n<p>The code samples that use <code>OpenAIChatClient</code> (e.g., Lesson 14 hotel booking workflow) will automatically detect and use your MiniMax configuration when <code>MINIMAX_API_KEY</code> is set.</p>\n<h2 id=\"ai-sec-17\" class=\"cs-h2\">Alternative Provider: Novita AI (OpenAI-Compatible)</h2>\n<p><a href=\"https://novita.ai/llm-api\" target=\"_blank\" rel=\"noopener noreferrer\">Novita AI</a> provides an OpenAI-compatible API for open-source and frontier LLMs (DeepSeek, Llama, Qwen, and more). Since the Microsoft Agent Framework's <code>OpenAIChatClient</code> works with any OpenAI-compatible endpoint, you can use Novita AI as a drop-in alternative to Azure OpenAI or OpenAI.</p>\n<p>Add these variables to your <code>.env</code> file:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>NOVITA_API_KEY</code></td><td><a href=\"https://novita.ai/settings/key-management\" target=\"_blank\" rel=\"noopener noreferrer\">Novita AI Dashboard</a> → API Keys</td></tr>\n<tr><td><code>NOVITA_BASE_URL</code></td><td>Use <code>https://api.novita.ai/openai/v1</code> (default value)</td></tr>\n<tr><td><code>NOVITA_MODEL_ID</code></td><td>Model name to use (e.g., <code>moonshotai/kimi-k3</code>)</td></tr>\n</tbody></table></div>\n<p><strong>Example models</strong>: <code>moonshotai/kimi-k3</code>, <code>zai-org/glm-5.2</code>, <code>deepseek/deepseek-v4-flash-0731</code>. Novita AI also hosts many other open-source model families (Llama, Qwen, GLM, and more) — check the <a href=\"https://novita.ai/llm-api\" target=\"_blank\" rel=\"noopener noreferrer\">Novita AI model library</a> for the current list of available models and their model IDs.</p>\n<p>The current samples do not automatically consume <code>NOVITA_*</code> variables. To use Novita AI, pass these values explicitly when constructing <code>OpenAIChatClient</code> in the sample you are running.</p>\n<h2 id=\"ai-sec-18\" class=\"cs-h2\">Alternative Provider: Foundry Local (Run Models On-Device)</h2>\n<p><a href=\"https://foundrylocal.ai\" target=\"_blank\" rel=\"noopener noreferrer\">Foundry Local</a> is a lightweight runtime that downloads, manages, and serves language models <strong>entirely on your own machine</strong> through an OpenAI-compatible API — no cloud required.</p>\n<p>Because the Microsoft Agent Framework's <code>OpenAIChatClient</code> works with any OpenAI-compatible endpoint, Foundry Local is a drop-in local alternative to Azure OpenAI.</p>\n<p><strong>1. Install Foundry Local</strong></p>\n<pre class=\"cs-code\"><code># Windows\nwinget install Microsoft.FoundryLocal\n\n# macOS\nbrew install foundrylocal</code></pre>\n<p><strong>2. Download and run a model</strong> (this also starts the local service):</p>\n<pre class=\"cs-code\"><code>foundry model list          # see available models\nfoundry model run phi-4-mini</code></pre>\n<p><strong>3. Install the Python SDK</strong> used to discover the local endpoint:</p>\n<pre class=\"cs-code\"><code>pip install foundry-local-sdk</code></pre>\n<p><strong>4. Point the Microsoft Agent Framework at your local model:</strong></p>\n<pre class=\"cs-code\"><code>from foundry_local import FoundryLocalManager\nfrom agent_framework.openai import OpenAIChatClient\n\n# Downloads (if needed) and serves the model locally, then discovers the endpoint/port.\nmanager = FoundryLocalManager(&quot;phi-4-mini&quot;)\n\nchat_client = OpenAIChatClient(\n    base_url=manager.endpoint,      # e.g. http://localhost:&lt;port&gt;/v1\n    api_key=manager.api_key,        # always &quot;not-required&quot; for Foundry Local\n    model_id=manager.get_model_info(&quot;phi-4-mini&quot;).id,\n)\n\nagent = chat_client.as_agent(\n    name=&quot;LocalAgent&quot;,\n    instructions=&quot;You are a helpful assistant running fully on-device.&quot;,\n)</code></pre>\n<blockquote class=\"cs-quote\"><strong>Note:</strong> Foundry Local exposes an OpenAI-compatible <strong>Chat Completions</strong> endpoint. Use it for local development and offline scenarios. For the full <strong>Responses API</strong> feature set (stateful conversations, etc.), use Azure OpenAI or a Microsoft Foundry project.</blockquote>\n<h2 id=\"ai-sec-19\" class=\"cs-h2\">Additional Setup for Lesson 8 (Bing Grounding Workflow)</h2>\n<p>The conditional workflow notebook in lesson 8 uses <strong>Bing grounding</strong> via Microsoft Foundry. If you plan to run that sample, add this variable to your <code>.env</code> file:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Variable</th><th>Where to find it</th></tr></thead><tbody>\n<tr><td><code>BING_CONNECTION_ID</code></td><td>Microsoft Foundry portal → your project → <strong>Management</strong> → <strong>Connected resources</strong> → your Bing connection → copy the connection ID</td></tr>\n</tbody></table></div>\n<h2 id=\"ai-sec-20\" class=\"cs-h2\">Troubleshooting</h2>\n<h3 id=\"ai-sec-21\" class=\"cs-h3\">SSL Certificate Verification Errors on macOS</h3>\n<p>If you are on macOS and encounter an error like:</p>\n<pre class=\"cs-code\"><code>ssl.SSLCertVerificationError: [SSL: CERTIFICATE_VERIFY_FAILED] certificate verify failed: self-signed certificate in certificate chain</code></pre>\n<p>This is a known issue with Python on macOS where the system SSL certificates are not automatically trusted. Try the following solutions in order:</p>\n<p><strong>Option 1: Run Python's Install Certificates script (recommended)</strong></p>\n<pre class=\"cs-code\"><code># Replace 3.XX with your installed Python version (e.g., 3.12 or 3.13):\n/Applications/Python\\ 3.XX/Install\\ Certificates.command</code></pre>\n<p><strong>Option 2: Use <code>connection_verify=False</code> in your notebook (for GitHub Models notebooks only)</strong></p>\n<p>In the Lesson 6 notebook (<code>06-building-trustworthy-agents/code_samples/06-system-message-framework.ipynb</code>), a commented-out workaround is already included. Uncomment <code>connection_verify=False</code> when you hit certificate errors:</p>\n<pre class=\"cs-code\"><code>client = ChatCompletionsClient(\n    endpoint=endpoint,\n    credential=AzureKeyCredential(token),\n    connection_verify=False,  # Disable SSL verification if you encounter certificate errors\n)</code></pre>\n<blockquote class=\"cs-quote\"><strong>⚠️ Warning:</strong> Disabling SSL verification (<code>connection_verify=False</code>) reduces security by skipping certificate validation. Use this only as a temporary workaround in development environments. Never use it in production.</blockquote>\n<p><strong>Option 3: Install and use <code>truststore</code></strong></p>\n<pre class=\"cs-code\"><code>pip install truststore</code></pre>\n<p>Then add the following at the top of your notebook or script before making any network calls:</p>\n<pre class=\"cs-code\"><code>import truststore\ntruststore.inject_into_ssl()</code></pre>\n<h2 id=\"ai-sec-22\" class=\"cs-h2\">Stuck Somewhere?</h2>\n<p>If you have any issues running this setup, hop into our &lt;a href=\"https://discord.gg/kzRShWzttr\" target=\"_blank\"&gt;Azure AI Community Discord&lt;/a&gt; or &lt;a href=\"https://github.com/microsoft/ai-agents-for-beginners/issues?WT.mc_id=academic-105485-koreyst\" target=\"_blank\"&gt;create an issue&lt;/a&gt;.</p>\n<h2 id=\"ai-sec-23\" class=\"cs-h2\">Next Lesson</h2>\n<p>You are now ready to run the code for this course. Happy learning more about the world of AI Agents!</p>\n<p><strong>Introduction to AI Agents and Agent Use Cases</strong></p>"}, "vi": {"title": "Thiết lập Khóa học", "sections": [{"id": "ai-sec-1", "level": 2, "title": "Giới thiệu"}, {"id": "ai-sec-2", "level": 2, "title": "Tham gia Cộng đồng Người học và Nhận Hỗ trợ"}, {"id": "ai-sec-3", "level": 2, "title": "Sao chép hoặc Tạo Fork repo này"}, {"id": "ai-sec-4", "level": 3, "title": "Sao chép Shallow (khuyến nghị cho workshop / Codespaces)"}, {"id": "ai-sec-5", "level": 2, "title": "Chạy Mã Nguồn"}, {"id": "ai-sec-6", "level": 2, "title": "Yêu cầu"}, {"id": "ai-sec-7", "level": 2, "title": "Thiết lập VSCode"}, {"id": "ai-sec-8", "level": 2, "title": "Thiết lập Microsoft Foundry và Microsoft Foundry Agent Service"}, {"id": "ai-sec-9", "level": 3, "title": "Bước 1: Tạo Microsoft Foundry Project"}, {"id": "ai-sec-10", "level": 3, "title": "Bước 2: Lấy Endpoint Dự án và Tên Triển khai Mô hình"}, {"id": "ai-sec-11", "level": 3, "title": "Bước 3: Đăng nhập Azure với `az login`"}, {"id": "ai-sec-12", "level": 3, "title": "Bước 4: Tạo file `.env` của bạn"}, {"id": "ai-sec-13", "level": 3, "title": "Bước 5: Cài đặt các thư viện Python"}, {"id": "ai-sec-14", "level": 2, "title": "Thiết lập Tùy chọn: Azure AI Search (Bài 5 và 16)"}, {"id": "ai-sec-15", "level": 2, "title": "Thiết lập thêm cho các bài gọi Azure OpenAI Trực tiếp (Bài 6 và 8)"}, {"id": "ai-sec-16", "level": 2, "title": "Nhà cung cấp thay thế: MiniMax (tương thích OpenAI)"}, {"id": "ai-sec-17", "level": 2, "title": "Nhà cung cấp thay thế: Novita AI (Tương thích OpenAI)"}, {"id": "ai-sec-18", "level": 2, "title": "Nhà cung cấp thay thế: Foundry Local (Chạy mô hình trên thiết bị)"}, {"id": "ai-sec-19", "level": 2, "title": "Thiết lập bổ sung cho Bài học 8 (Quy trình làm việc nền tảng Bing)"}, {"id": "ai-sec-20", "level": 2, "title": "Khắc phục sự cố"}, {"id": "ai-sec-21", "level": 3, "title": "Lỗi xác thực chứng chỉ SSL trên macOS"}, {"id": "ai-sec-22", "level": 2, "title": "Bị mắc kẹt ở đâu đó?"}, {"id": "ai-sec-23", "level": 2, "title": "Bài học tiếp theo"}], "html": "<h1 id=\"ai-sec-1\" class=\"cs-h1\">Thiết lập Khóa học</h1>\n<h2 id=\"ai-sec-1\" class=\"cs-h2\">Giới thiệu</h2>\n<p>Bài học này sẽ trình bày cách chạy các mẫu mã nguồn trong khóa học này.</p>\n<h2 id=\"ai-sec-2\" class=\"cs-h2\">Tham gia Cộng đồng Người học và Nhận Hỗ trợ</h2>\n<p>Trước khi bắt đầu sao chép repo của bạn, hãy tham gia <a href=\"https://aka.ms/ai-agents/discord\" target=\"_blank\" rel=\"noopener noreferrer\">kênh Discord AI Agents For Beginners</a> để nhận được hỗ trợ về quá trình thiết lập, giải đáp thắc mắc về khóa học, hoặc kết nối với các người học khác.</p>\n<h2 id=\"ai-sec-3\" class=\"cs-h2\">Sao chép hoặc Tạo Fork repo này</h2>\n<p>Để bắt đầu, vui lòng sao chép hoặc tạo fork Kho Lưu trữ GitHub. Điều này sẽ tạo ra phiên bản của riêng bạn của tài liệu khóa học để bạn có thể chạy, kiểm tra và chỉnh sửa mã nguồn!</p>\n<p>Việc này có thể thực hiện bằng cách nhấp vào đường link &lt;a href=\"https://github.com/microsoft/ai-agents-for-beginners/fork\" target=\"_blank\"&gt;tạo fork repo&lt;/a&gt;</p>\n<p>Bạn sẽ có phiên bản fork riêng của khóa học này tại đường link sau:</p>\n<blockquote class=\"cs-quote\">[Figure: Forked Repo]</blockquote>\n<h3 id=\"ai-sec-4\" class=\"cs-h3\">Sao chép Shallow (khuyến nghị cho workshop / Codespaces)</h3>\n<blockquote class=\"cs-quote\">Kho lưu trữ đầy đủ có thể rất lớn (~3 GB) khi bạn tải về toàn bộ lịch sử và tất cả các file. Nếu bạn chỉ tham gia workshop hoặc chỉ cần một vài thư mục bài học, sao chép shallow (hoặc sao chép sparse) sẽ tải ít dữ liệu hơn nhiều.</blockquote>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Sao chép shallow nhanh — lịch sử tối thiểu, tất cả file</h4>\n<p>Thay thế <code>&lt;your-username&gt;</code> trong các lệnh dưới đây bằng URL fork của bạn (hoặc URL upstream nếu bạn muốn).</p>\n<p>Để sao chép chỉ lịch sử commit mới nhất (tải xuống nhỏ):</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<p>Để sao chép một nhánh cụ thể:</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 --branch &lt;branch-name&gt; https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Sao chép Partial (sparse) — số lượng blob tối thiểu + chỉ những thư mục được chọn</h4>\n<p>Cách này sử dụng partial clone và sparse-checkout (yêu cầu Git 2.25+ và khuyến nghị Git hiện đại hỗ trợ partial clone):</p>\n<pre class=\"cs-code\"><code>git clone --depth 1 --filter=blob:none --sparse https://github.com/&lt;your-username&gt;/ai-agents-for-beginners.git</code></pre>\n<p>Chuyển vào thư mục repo:</p>\n<pre class=\"cs-code\"><code>cd ai-agents-for-beginners</code></pre>\n<p>Sau đó chỉ định những thư mục bạn muốn (ví dụ dưới đây có hai thư mục):</p>\n<pre class=\"cs-code\"><code>git sparse-checkout set 00-course-setup 01-intro-to-ai-agents</code></pre>\n<p>Sau khi sao chép và xác nhận các file, nếu bạn chỉ cần các file và muốn giải phóng dung lượng (không cần lịch sử git), hãy xóa metadata repo đi (💀không thể phục hồi — bạn sẽ mất tất cả chức năng Git):</p>\n<pre class=\"cs-code\"><code># zsh/bash\nrm -rf .git</code></pre>\n<pre class=\"cs-code\"><code># PowerShell\nRemove-Item -Recurse -Force .git</code></pre>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Sử dụng GitHub Codespaces (khuyến nghị để tránh tải xuống lớn trên máy cục bộ)</h4>\n<ul class=\"cs-list\">\n<li>Tạo một Codespace mới cho repo này qua <a href=\"https://github.com/codespaces\" target=\"_blank\" rel=\"noopener noreferrer\">Giao diện GitHub</a>.</li>\n</ul>\n<ul class=\"cs-list\">\n<li>Trong terminal của codespace mới tạo, chạy một trong các lệnh shallow/sparse clone ở trên để chỉ đưa những thư mục bài học cần thiết vào workspace Codespace.</li>\n<li>Tùy chọn: sau khi sao chép trong Codespaces, xóa .git để thu hồi thêm dung lượng (xem các lệnh xóa ở trên).</li>\n<li>Lưu ý: Nếu bạn muốn mở trực tiếp repo trong Codespaces (không sao chép thêm), Codespaces sẽ xây dựng môi trường devcontainer và có thể vẫn cung cấp nhiều hơn bạn cần.</li>\n</ul>\n<h4 id=\"ai-sec-5\" class=\"cs-h4\">Mẹo</h4>\n<ul class=\"cs-list\">\n<li>Luôn thay URL sao chép thành phiên bản fork của bạn nếu bạn muốn chỉnh sửa/commit.</li>\n<li>Nếu sau này bạn cần thêm lịch sử hoặc file, bạn có thể fetch chúng hoặc điều chỉnh sparse-checkout để bao gồm thêm thư mục.</li>\n</ul>\n<h2 id=\"ai-sec-5\" class=\"cs-h2\">Chạy Mã Nguồn</h2>\n<p>Khóa học cung cấp một loạt các Jupyter Notebooks mà bạn có thể chạy để thực hành xây dựng AI Agents.</p>\n<p>Các mẫu mã nguồn sử dụng <strong>Microsoft Agent Framework (MAF)</strong> với <code>FoundryChatClient</code>, kết nối tới <strong>Microsoft Foundry Agent Service V2</strong> (API Responses) thông qua <strong>Microsoft Foundry</strong>.</p>\n<p>Tất cả notebooks Python đều được đánh dấu <code>*-python-agent-framework.ipynb</code>.</p>\n<h2 id=\"ai-sec-6\" class=\"cs-h2\">Yêu cầu</h2>\n<ul class=\"cs-list\">\n<li>Python 3.12+</li>\n<li><strong>LƯU Ý</strong>: Nếu bạn chưa cài Python3.12, hãy chắc chắn cài đặt. Sau đó tạo môi trường venv bằng python3.12 để đảm bảo phiên bản đúng được cài từ file requirements.txt.</li>\n</ul>\n<blockquote class=\"cs-quote\">Ví dụ</blockquote>\n<p>Tạo thư mục venv Python:</p>\n<pre class=\"cs-code\"><code>    python -m venv venv</code></pre>\n<p>Sau đó kích hoạt môi trường venv cho:</p>\n<pre class=\"cs-code\"><code>    # zsh/bash\n    source venv/bin/activate</code></pre>\n<pre class=\"cs-code\"><code>    # Command Prompt for Windows\n    venv\\Scripts\\activate</code></pre>\n<ul class=\"cs-list\">\n<li>.NET 10+: Đối với các mẫu mã sử dụng .NET, hãy chắc chắn bạn đã cài <a href=\"https://dotnet.microsoft.com/download/dotnet/10.0\" target=\"_blank\" rel=\"noopener noreferrer\">.NET 10 SDK</a> hoặc mới hơn. Sau đó, kiểm tra phiên bản .NET SDK đã cài:</li>\n</ul>\n<pre class=\"cs-code\"><code>    dotnet --list-sdks</code></pre>\n<ul class=\"cs-list\">\n<li><strong>Azure CLI</strong> — Cần thiết cho xác thực. Cài đặt tại <a href=\"https://aka.ms/installazurecli\" target=\"_blank\" rel=\"noopener noreferrer\">aka.ms/installazurecli</a>.</li>\n<li><strong>Azure Subscription</strong> — Để truy cập Microsoft Foundry và Microsoft Foundry Agent Service.</li>\n<li><strong>Microsoft Foundry Project</strong> — Một dự án có mô hình đã triển khai (ví dụ <code>gpt-5-mini</code>). Xem <strong>Bước 1</strong> bên dưới.</li>\n</ul>\n<p>Chúng tôi đã bao gồm file <code>requirements.txt</code> ở thư mục gốc của repo chứa tất cả gói Python cần thiết để chạy các mẫu mã.</p>\n<p>Bạn có thể cài đặt chúng bằng cách chạy lệnh sau trong terminal ở thư mục gốc repo:</p>\n<pre class=\"cs-code\"><code>pip install -r requirements.txt</code></pre>\n<p>Chúng tôi khuyên bạn nên tạo môi trường ảo Python để tránh xung đột và các vấn đề.</p>\n<h2 id=\"ai-sec-7\" class=\"cs-h2\">Thiết lập VSCode</h2>\n<p>Đảm bảo bạn đang dùng đúng phiên bản Python trong VSCode.</p>\n<h2 id=\"ai-sec-8\" class=\"cs-h2\">Thiết lập Microsoft Foundry và Microsoft Foundry Agent Service</h2>\n<h3 id=\"ai-sec-9\" class=\"cs-h3\">Bước 1: Tạo Microsoft Foundry Project</h3>\n<p>Bạn cần có một <strong>hub</strong> và <strong>project</strong> trong Microsoft Foundry với mô hình đã triển khai để chạy các notebook.</p>\n<ol class=\"cs-list\">\n<li>Vào <a href=\"https://ai.azure.com\" target=\"_blank\" rel=\"noopener noreferrer\">ai.azure.com</a> và đăng nhập bằng tài khoản Azure của bạn.</li>\n<li>Tạo một <strong>hub</strong> (hoặc dùng hub hiện có). Xem: <a href=\"https://learn.microsoft.com/azure/ai-foundry/concepts/ai-resources\" target=\"_blank\" rel=\"noopener noreferrer\">Tổng quan về tài nguyên Hub</a>.</li>\n<li>Trong hub, tạo một <strong>project</strong>.</li>\n<li>Triển khai một mô hình (ví dụ <code>gpt-5-mini</code>) từ <strong>Models + Endpoints</strong> → <strong>Deploy model</strong>.</li>\n</ol>\n<h3 id=\"ai-sec-10\" class=\"cs-h3\">Bước 2: Lấy Endpoint Dự án và Tên Triển khai Mô hình</h3>\n<p>Từ dự án của bạn trong cổng Microsoft Foundry:</p>\n<ul class=\"cs-list\">\n<li><strong>Project Endpoint</strong> — Vào trang <strong>Overview</strong> và sao chép URL endpoint.</li>\n</ul>\n<blockquote class=\"cs-quote\">[Figure: Project Connection String]</blockquote>\n<ul class=\"cs-list\">\n<li><strong>Model Deployment Name</strong> — Vào <strong>Models + Endpoints</strong>, chọn mô hình đã triển khai, và ghi lại <strong>Deployment name</strong> (ví dụ <code>gpt-5-mini</code>).</li>\n</ul>\n<h3 id=\"ai-sec-11\" class=\"cs-h3\">Bước 3: Đăng nhập Azure với <code>az login</code></h3>\n<p>Hầu hết các notebook xác thực qua <strong>đăng nhập Azure CLI</strong> của bạn — dùng <code>AzureCliCredential</code> hoặc <code>DefaultAzureCredential</code> (cả hai đều dựa vào phiên <code>az login</code>) từ gói <code>azure-identity</code> — nên không cần API key. Một vài bài học và tích hợp tùy chọn dùng API key; kiểm tra yêu cầu từng bài học để biết biến môi trường thêm. Bạn cần đăng nhập qua Azure CLI.</p>\n<ol class=\"cs-list\">\n<li><strong>Cài Azure CLI</strong> nếu bạn chưa có: <a href=\"https://aka.ms/installazurecli\" target=\"_blank\" rel=\"noopener noreferrer\">aka.ms/installazurecli</a></li>\n</ol>\n<ol class=\"cs-list\">\n<li><strong>Đăng nhập</strong> bằng cách chạy:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az login</code></pre>\n<p>Hoặc nếu bạn đang ở môi trường remote/Codespace không có trình duyệt:</p>\n<pre class=\"cs-code\"><code>    az login --use-device-code</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Chọn subscription</strong> nếu được yêu cầu — chọn subscription chứa dự án Foundry của bạn.</li>\n</ol>\n<ol class=\"cs-list\">\n<li><strong>Xác nhận</strong> bạn đã đăng nhập:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az account show</code></pre>\n<blockquote class=\"cs-quote\"><strong>Tại sao dùng <code>az login</code>?</strong> Các notebook xác thực bằng <code>AzureCliCredential</code> (hoặc <code>DefaultAzureCredential</code>, cũng dựa vào đăng nhập Azure CLI) từ gói <code>azure-identity</code>. Nghĩa là phiên Azure CLI của bạn cung cấp chứng thực — không cần API key hay bí mật trong file <code>.env</code>. Đây là <a href=\"https://learn.microsoft.com/azure/developer/ai/keyless-connections\" target=\"_blank\" rel=\"noopener noreferrer\">thực hành bảo mật tốt nhất</a>.</blockquote>\n<h3 id=\"ai-sec-12\" class=\"cs-h3\">Bước 4: Tạo file <code>.env</code> của bạn</h3>\n<p>Sao chép file mẫu:</p>\n<pre class=\"cs-code\"><code># zsh/bash\ncp .env.example .env</code></pre>\n<pre class=\"cs-code\"><code># PowerShell\nCopy-Item .env.example .env</code></pre>\n<p>Mở <code>.env</code> và điền hai giá trị sau:</p>\n<pre class=\"cs-code\"><code>AZURE_AI_PROJECT_ENDPOINT=https://&lt;your-project&gt;.services.ai.azure.com/api/projects/&lt;your-project-id&gt;\nAZURE_AI_MODEL_DEPLOYMENT_NAME=gpt-5-mini</code></pre>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>AZURE_AI_PROJECT_ENDPOINT</code></td><td>Cổng Foundry → dự án của bạn → trang <strong>Overview</strong></td></tr>\n<tr><td><code>AZURE_AI_MODEL_DEPLOYMENT_NAME</code></td><td>Cổng Foundry → <strong>Models + Endpoints</strong> → tên mô hình đã triển khai</td></tr>\n</tbody></table></div>\n<p>Đó là tất cả cho hầu hết các bài học! Các notebook sẽ tự động xác thực qua phiên <code>az login</code> của bạn.</p>\n<h3 id=\"ai-sec-13\" class=\"cs-h3\">Bước 5: Cài đặt các thư viện Python</h3>\n<pre class=\"cs-code\"><code>pip install -r requirements.txt</code></pre>\n<p>Chúng tôi khuyến nghị chạy lệnh này trong môi trường ảo bạn đã tạo trước đó.</p>\n<h2 id=\"ai-sec-14\" class=\"cs-h2\">Thiết lập Tùy chọn: Azure AI Search (Bài 5 và 16)</h2>\n<p>Notebook Bài 5 (Agentic RAG) và Bài 16 chạy trực tiếp với cơ sở kiến thức <strong>lưu trong bộ nhớ</strong> — không cần tài nguyên Azure thêm. Nếu bạn muốn sử dụng <strong>Azure AI Search</strong> thật, lưu ý rằng notebook Bài 16 hiện dùng xác thực bằng khóa: nó chuyển từ tìm kiếm trong bộ nhớ sang Azure AI Search chỉ khi <strong>cả hai</strong> biến <code>AZURE_SEARCH_SERVICE_ENDPOINT</code> <strong>và</strong> <code>AZURE_SEARCH_API_KEY</code> được đặt, nếu không vẫn dùng tìm kiếm trong bộ nhớ — nên để chạy trên chỉ mục thực bạn phải đặt khóa admin. Xác thực không khóa với Microsoft Entra ID (RBAC) là cách được khuyến nghị cho mã sản xuất, phù hợp với quy trình <code>az login</code> dùng trong toàn khóa học.</p>\n<p>Các bước RBAC dưới đây áp dụng cho các mẫu trong hướng dẫn thiết lập và mã của bạn. Chúng không kích hoạt xác thực không khóa trong notebook Bài 16; Bài 16 vẫn cần cả endpoint và khóa admin để dùng Azure AI Search.</p>\n<ol class=\"cs-list\">\n<li><strong>Bật quyền truy cập dựa trên vai trò</strong> trên dịch vụ tìm kiếm của bạn:</li>\n</ol>\n<pre class=\"cs-code\"><code>    az search service update --name &lt;service-name&gt; --resource-group &lt;resource-group&gt; --auth-options aadOrApiKey</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Gán cho bạn các vai trò cần thiết</strong> (tạo/tải chỉ mục và truy vấn):</li>\n</ol>\n<pre class=\"cs-code\"><code>    az role assignment create --assignee &lt;your-user-or-principal-id&gt; --role &quot;Search Service Contributor&quot; --scope $(az search service show -g &lt;resource-group&gt; -n &lt;service-name&gt; --query id -o tsv)\n    az role assignment create --assignee &lt;your-user-or-principal-id&gt; --role &quot;Search Index Data Contributor&quot; --scope $(az search service show -g &lt;resource-group&gt; -n &lt;service-name&gt; --query id -o tsv)</code></pre>\n<ol class=\"cs-list\">\n<li><strong>Thêm endpoint</strong> vào file <code>.env</code> của bạn:</li>\n</ol>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>AZURE_SEARCH_SERVICE_ENDPOINT</code></td><td>Cổng Azure → tài nguyên <strong>Azure AI Search</strong> của bạn → <strong>Overview</strong> → URL</td></tr>\n<tr><td><code>AZURE_SEARCH_API_KEY</code></td><td>Bắt buộc (cùng endpoint) để bật Azure AI Search trong notebook Bài 16, dùng xác thực bằng khóa. Cổng Azure → <strong>Settings</strong> → <strong>Keys</strong> → khóa admin chính</td></tr>\n</tbody></table></div>\n<blockquote class=\"cs-quote\"><strong>Tại sao không dùng khóa?</strong> Khóa admin cấp quyền ghi toàn bộ cho dịch vụ tìm kiếm và có thể bị lộ qua file <code>.env</code>. Với RBAC, danh tính đăng nhập <code>az login</code> của bạn được dùng thay — cùng mẫu Entra ID không khóa mà các notebook khóa học dùng (qua <code>AzureCliCredential</code> / <code>DefaultAzureCredential</code>). Xem thêm <a href=\"https://learn.microsoft.com/azure/search/search-security-rbac\" target=\"_blank\" rel=\"noopener noreferrer\">Kết nối tới Azure AI Search dùng vai trò</a>.</blockquote>\n<p>Xem <strong>hướng dẫn thiết lập Azure AI Search</strong> để có các mẫu tạo chỉ mục đầy đủ bằng Python và .NET.</p>\n<h2 id=\"ai-sec-15\" class=\"cs-h2\">Thiết lập thêm cho các bài gọi Azure OpenAI Trực tiếp (Bài 6 và 8)</h2>\n<p>Một số notebook ở bài 6 và 8 gọi <strong>Azure OpenAI</strong> trực tiếp (dùng <strong>Responses API</strong>) thay vì qua dự án Microsoft Foundry. Các mẫu này trước đây dùng GitHub Models, đã bị ngừng hỗ trợ và không hỗ trợ Responses API. Thêm các biến này vào file <code>.env</code> của bạn:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>AZURE_OPENAI_ENDPOINT</code></td><td>Cổng Azure → tài nguyên <strong>Azure OpenAI</strong> của bạn → <strong>Keys and Endpoint</strong> → Endpoint (ví dụ <code>https://&lt;your-resource&gt;.openai.azure.com</code>)</td></tr>\n<tr><td><code>AZURE_OPENAI_DEPLOYMENT</code></td><td>Tên mô hình đã triển khai (ví dụ <code>gpt-5-mini</code>) hỗ trợ Responses API</td></tr>\n<tr><td><code>AZURE_OPENAI_API_KEY</code></td><td>Tùy chọn — chỉ dùng nếu bạn dùng xác thực bằng khóa thay vì <code>az login</code> / Entra ID</td></tr>\n</tbody></table></div>\n<blockquote class=\"cs-quote\">Responses API dùng endpoint ổn định <code>/openai/v1/</code>, nên không cần <code>api-version</code>. Đăng nhập với <code>az login</code> để dùng xác thực Entra ID không khóa.</blockquote>\n<h2 id=\"ai-sec-16\" class=\"cs-h2\">Nhà cung cấp thay thế: MiniMax (tương thích OpenAI)</h2>\n<p><a href=\"https://platform.minimaxi.com/\" target=\"_blank\" rel=\"noopener noreferrer\">MiniMax</a> cung cấp các mô hình ngữ cảnh lớn (lên tới 204K token) qua API tương thích OpenAI. Vì Microsoft Agent Framework's <code>OpenAIChatClient</code> có thể làm việc với bất kỳ endpoint tương thích OpenAI nào, bạn có thể dùng MiniMax như là lựa chọn thay thế cho các bài sử dụng <code>OpenAIChatClient</code>.</p>\n<p>Thêm các biến này vào file <code>.env</code> của bạn:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>MINIMAX_API_KEY</code></td><td><a href=\"https://platform.minimaxi.com/\" target=\"_blank\" rel=\"noopener noreferrer\">MiniMax Platform</a> → API Keys</td></tr>\n<tr><td><code>MINIMAX_BASE_URL</code></td><td>Dùng <code>https://api.minimax.io/v1</code> (giá trị mặc định)</td></tr>\n<tr><td><code>MINIMAX_MODEL_ID</code></td><td>Tên mô hình sử dụng (ví dụ <code>MiniMax-M3</code>)</td></tr>\n</tbody></table></div>\n<p><strong>Mô hình ví dụ</strong>: <code>MiniMax-M3</code> (khuyến nghị), <code>MiniMax-M2.7</code>, <code>MiniMax-M2.7-highspeed</code> (phản hồi nhanh hơn). Tên mô hình và khả dụng có thể thay đổi theo thời gian, và quyền truy cập vào mô hình nào tùy thuộc tài khoản của bạn.</p>\n<p>Các mẫu mã dùng <code>OpenAIChatClient</code> (ví dụ workflow đặt phòng khách sạn Bài 14) sẽ tự động phát hiện và sử dụng cấu hình MiniMax của bạn khi <code>MINIMAX_API_KEY</code> được thiết lập.</p>\n<h2 id=\"ai-sec-17\" class=\"cs-h2\">Nhà cung cấp thay thế: Novita AI (Tương thích OpenAI)</h2>\n<p><a href=\"https://novita.ai/llm-api\" target=\"_blank\" rel=\"noopener noreferrer\">Novita AI</a> cung cấp API tương thích OpenAI cho các mô hình ngôn ngữ mở và tiên tiến (DeepSeek, Llama, Qwen và nhiều hơn nữa). Vì <code>OpenAIChatClient</code> của Microsoft Agent Framework hoạt động với bất kỳ điểm cuối tương thích OpenAI nào, bạn có thể sử dụng Novita AI như một lựa chọn thay thế thay thế hoàn toàn cho Azure OpenAI hoặc OpenAI.</p>\n<p>Thêm các biến này vào tệp <code>.env</code> của bạn:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>NOVITA_API_KEY</code></td><td><a href=\"https://novita.ai/settings/key-management\" target=\"_blank\" rel=\"noopener noreferrer\">Bảng điều khiển Novita AI</a> → Khóa API</td></tr>\n<tr><td><code>NOVITA_BASE_URL</code></td><td>Sử dụng <code>https://api.novita.ai/openai/v1</code> (giá trị mặc định)</td></tr>\n<tr><td><code>NOVITA_MODEL_ID</code></td><td>Tên mô hình để sử dụng (ví dụ: <code>moonshotai/kimi-k3</code>)</td></tr>\n</tbody></table></div>\n<p><strong>Mẫu mô hình ví dụ</strong>: <code>moonshotai/kimi-k3</code>, <code>zai-org/glm-5.2</code>, <code>deepseek/deepseek-v4-flash-0731</code>. Novita AI cũng lưu trữ nhiều họ mô hình mã nguồn mở khác (Llama, Qwen, GLM và nhiều hơn nữa) — xem <a href=\"https://novita.ai/llm-api\" target=\"_blank\" rel=\"noopener noreferrer\">thư viện mô hình Novita AI</a> để biết danh sách hiện tại các mô hình có sẵn và ID mô hình của chúng.</p>\n<p>Các mẫu hiện tại không tự động sử dụng các biến <code>NOVITA_*</code>. Để sử dụng Novita AI, hãy truyền các giá trị này rõ ràng khi xây dựng <code>OpenAIChatClient</code> trong mẫu bạn đang chạy.</p>\n<h2 id=\"ai-sec-18\" class=\"cs-h2\">Nhà cung cấp thay thế: Foundry Local (Chạy mô hình trên thiết bị)</h2>\n<p><a href=\"https://foundrylocal.ai\" target=\"_blank\" rel=\"noopener noreferrer\">Foundry Local</a> là một runtime nhẹ tải xuống, quản lý và phục vụ các mô hình ngôn ngữ <strong>hoàn toàn trên máy của bạn</strong> thông qua API tương thích OpenAI — không cần đám mây.</p>\n<p>Vì <code>OpenAIChatClient</code> của Microsoft Agent Framework hoạt động với bất kỳ điểm cuối tương thích OpenAI nào, Foundry Local là một lựa chọn thay thế cục bộ thay thế cho Azure OpenAI.</p>\n<p><strong>1. Cài đặt Foundry Local</strong></p>\n<pre class=\"cs-code\"><code># Windows\nwinget install Microsoft.FoundryLocal\n\n# macOS\nbrew install foundrylocal</code></pre>\n<p><strong>2. Tải xuống và chạy một mô hình</strong> (điều này cũng khởi động dịch vụ cục bộ):</p>\n<pre class=\"cs-code\"><code>foundry model list          # xem các mẫu có sẵn\nfoundry model run phi-4-mini</code></pre>\n<p><strong>3. Cài đặt SDK Python</strong> được sử dụng để phát hiện điểm cuối cục bộ:</p>\n<pre class=\"cs-code\"><code>pip install foundry-local-sdk</code></pre>\n<p><strong>4. Đặt Microsoft Agent Framework trỏ tới mô hình cục bộ của bạn:</strong></p>\n<pre class=\"cs-code\"><code>from foundry_local import FoundryLocalManager\nfrom agent_framework.openai import OpenAIChatClient\n\n# Tải xuống (nếu cần) và phục vụ mô hình cục bộ, sau đó phát hiện điểm cuối/cổng.\nmanager = FoundryLocalManager(&quot;phi-4-mini&quot;)\n\nchat_client = OpenAIChatClient(\n    base_url=manager.endpoint,      # ví dụ http://localhost:&lt;port&gt;/v1\n    api_key=manager.api_key,        # luôn luôn &quot;không cần thiết&quot; đối với Foundry Local\n    model_id=manager.get_model_info(&quot;phi-4-mini&quot;).id,\n)\n\nagent = chat_client.as_agent(\n    name=&quot;LocalAgent&quot;,\n    instructions=&quot;You are a helpful assistant running fully on-device.&quot;,\n)</code></pre>\n<blockquote class=\"cs-quote\"><strong>Lưu ý:</strong> Foundry Local cung cấp một điểm cuối <strong>Chat Completions</strong> tương thích OpenAI. Sử dụng nó cho phát triển cục bộ và các kịch bản ngoại tuyến. Để sử dụng đầy đủ bộ tính năng <strong>Responses API</strong> (cuộc hội thoại có trạng thái, v.v.), hãy sử dụng Azure OpenAI hoặc một dự án Microsoft Foundry.</blockquote>\n<h2 id=\"ai-sec-19\" class=\"cs-h2\">Thiết lập bổ sung cho Bài học 8 (Quy trình làm việc nền tảng Bing)</h2>\n<p>Sổ tay quy trình điều kiện trong bài học 8 sử dụng <strong>nền tảng Bing</strong> qua Microsoft Foundry. Nếu bạn dự định chạy mẫu đó, hãy thêm biến này vào tệp <code>.env</code> của bạn:</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Biến</th><th>Nơi tìm thấy</th></tr></thead><tbody>\n<tr><td><code>BING_CONNECTION_ID</code></td><td>Cổng Microsoft Foundry → dự án của bạn → <strong>Quản lý</strong> → <strong>Tài nguyên kết nối</strong> → kết nối Bing của bạn → sao chép ID kết nối</td></tr>\n</tbody></table></div>\n<h2 id=\"ai-sec-20\" class=\"cs-h2\">Khắc phục sự cố</h2>\n<h3 id=\"ai-sec-21\" class=\"cs-h3\">Lỗi xác thực chứng chỉ SSL trên macOS</h3>\n<p>Nếu bạn đang dùng macOS và gặp lỗi như sau:</p>\n<pre class=\"cs-code\"><code>ssl.SSLCertVerificationError: [SSL: CERTIFICATE_VERIFY_FAILED] certificate verify failed: self-signed certificate in certificate chain</code></pre>\n<p>Đây là sự cố đã biết với Python trên macOS khi các chứng chỉ SSL của hệ thống không được tin cậy tự động. Hãy thử các giải pháp sau theo thứ tự:</p>\n<p><strong>Lựa chọn 1: Chạy script Cài đặt Chứng chỉ của Python (được khuyến nghị)</strong></p>\n<pre class=\"cs-code\"><code># Thay thế 3.XX bằng phiên bản Python bạn đã cài đặt (ví dụ: 3.12 hoặc 3.13):\n/Applications/Python\\ 3.XX/Install\\ Certificates.command</code></pre>\n<p><strong>Lựa chọn 2: Sử dụng <code>connection_verify=False</code> trong sổ tay của bạn (chỉ dành cho sổ tay Mô hình GitHub)</strong></p>\n<p>Trong sổ tay Bài học 6 (<code>06-building-trustworthy-agents/code_samples/06-system-message-framework.ipynb</code>), đã có một cách khắc phục được chú thích. Bỏ chú thích <code>connection_verify=False</code> khi bạn gặp lỗi chứng chỉ:</p>\n<pre class=\"cs-code\"><code>client = ChatCompletionsClient(\n    endpoint=endpoint,\n    credential=AzureKeyCredential(token),\n    connection_verify=False,  # Vô hiệu hóa xác minh SSL nếu bạn gặp lỗi chứng chỉ\n)</code></pre>\n<blockquote class=\"cs-quote\"><strong>⚠️ Cảnh báo:</strong> Tắt xác thực SSL (<code>connection_verify=False</code>) giảm độ an toàn bằng cách bỏ qua việc xác thực chứng chỉ. Chỉ sử dụng cách này như một giải pháp tạm thời trong môi trường phát triển. Không bao giờ sử dụng trong môi trường sản xuất.</blockquote>\n<p><strong>Lựa chọn 3: Cài đặt và sử dụng <code>truststore</code></strong></p>\n<pre class=\"cs-code\"><code>pip install truststore</code></pre>\n<p>Sau đó thêm đoạn sau lên đầu sổ tay hoặc tập lệnh của bạn trước khi thực hiện bất kỳ gọi mạng nào:</p>\n<pre class=\"cs-code\"><code>import truststore\ntruststore.inject_into_ssl()</code></pre>\n<h2 id=\"ai-sec-22\" class=\"cs-h2\">Bị mắc kẹt ở đâu đó?</h2>\n<p>Nếu bạn gặp bất kỳ sự cố nào khi chạy cài đặt này, hãy tham gia &lt;a href=\"https://discord.gg/kzRShWzttr\" target=\"_blank\"&gt;Discord Cộng đồng Azure AI&lt;/a&gt; hoặc &lt;a href=\"https://github.com/microsoft/ai-agents-for-beginners/issues?WT.mc_id=academic-105485-koreyst\" target=\"_blank\"&gt;tạo một issue&lt;/a&gt;.</p>\n<h2 id=\"ai-sec-23\" class=\"cs-h2\">Bài học tiếp theo</h2>\n<p>Bây giờ bạn đã sẵn sàng chạy mã cho khóa học này. Chúc bạn học tập vui vẻ và tìm hiểu thêm về thế giới của các Đại lý AI!</p>\n<p><strong>Giới thiệu về Đại lý AI và Các trường hợp sử dụng đại lý</strong></p>\n<p>---</p>\n<p><strong>Tuyên bố miễn trừ trách nhiệm</strong>: Tài liệu này đã được dịch bằng dịch vụ dịch thuật AI <a href=\"https://github.com/Azure/co-op-translator\" target=\"_blank\" rel=\"noopener noreferrer\">Co-op Translator</a>. Mặc dù chúng tôi cố gắng đảm bảo độ chính xác, xin lưu ý rằng bản dịch tự động có thể chứa lỗi hoặc sai sót. Tài liệu gốc bằng ngôn ngữ gốc nên được coi là nguồn tin chính thức. Đối với thông tin quan trọng, nên sử dụng dịch vụ dịch thuật chuyên nghiệp bởi con người. Chúng tôi không chịu trách nhiệm về bất kỳ hiểu lầm hoặc giải thích sai nào phát sinh từ việc sử dụng bản dịch này.</p>"}, "codeSamples": []};
